@@ -1 +1,1255 @@
 #include "aggregation.h"
+#include "execution.h"
+
+#include <numeric>
+#include <type_traits>
+
+namespace {
+
+using namespace batch;
+
+// Cliques have one ascending representation. Higher-order cliques are
+// generated inside each forward neighborhood. The bit masks accelerate the
+// intersections when that neighborhood fits in one machine word.
+struct CliqueGraph {
+    const DataGraph &g;
+    std::vector<int> offsets;
+    std::vector<int> neighbors;
+    std::vector<int> triangleStart;
+    std::vector<int> triangleEnds;
+    std::vector<int> middleEdge, farEdge;
+    std::vector<int> triangleLeft, triangleMiddle, firstEdge, vertexTriangleStart;
+    std::vector<uint64_t> links;
+    std::vector<int> edgeIds;
+    std::vector<int> edgeLeft;
+    std::vector<std::vector<int>> common;
+
+    explicit CliqueGraph(const DataGraph &g) : g(g), offsets(g.getNumVertices() + 1) {
+        neighbors.reserve(g.getNumEdges() / 2);
+        for (VertexID u = 0; u < g.getNumVertices(); ++u) {
+            ui d;
+            auto ns = g.getNeighborsLargerID(u, d);
+            neighbors.insert(neighbors.end(), ns, ns + d);
+            offsets[u + 1] = neighbors.size();
+        }
+    }
+
+    int edge(int a, int b) const {
+        if (a > b) std::swap(a, b);
+        return std::lower_bound(neighbors.begin() + offsets[a], neighbors.begin() + offsets[a+1], b)
+                - neighbors.begin();
+    }
+
+    void buildTriangles(const Triangle *tri) {
+        if (!triangleStart.empty()) return;
+        if (tri) {
+            triangleEnds.reserve(tri->triangleCnt/3);
+            middleEdge.reserve(tri->triangleCnt/3);
+            farEdge.reserve(tri->triangleCnt/3);
+        }
+        triangleStart.resize(neighbors.size()+1);
+        links.resize(neighbors.size());
+        for (int u = 0; u < (int)g.getNumVertices(); ++u) {
+            int end = offsets[u+1];
+            for (int e = offsets[u]; e < end; ++e) {
+                int v = neighbors[e];
+                if (tri) {
+                    triangleEnds.insert(triangleEnds.end(), tri->triend + tri->offset3[e],
+                                        tri->triend + tri->offset1[e+1]);
+                } else {
+                    std::set_intersection(neighbors.begin() + e + 1, neighbors.begin() + end,
+                                          neighbors.begin()+offsets[v], neighbors.begin()+offsets[v+1],
+                                          std::back_inserter(triangleEnds));
+                }
+                triangleStart[e+1] = triangleEnds.size();
+                int ac = e+1, bc = offsets[v];
+                uint64_t mask = 0;
+                for (int t = triangleStart[e]; t < triangleStart[e+1]; ++t) {
+                    int c = triangleEnds[t];
+                    while (neighbors[ac] < c) ++ac;
+                    while (neighbors[bc] < c) ++bc;
+                    middleEdge.push_back(ac);
+                    farEdge.push_back(bc);
+                    if (end - offsets[u] <= 64) mask |= uint64_t(1) << (ac - offsets[u]);
+                }
+                links[e] = mask;
+            }
+        }
+    }
+
+    void indexEdges() {
+        if (!edgeIds.empty()) return;
+        edgeIds.resize(g.getNumEdges());
+        std::vector<int> cursor(g.getOffsets(),g.getOffsets()+g.getNumVertices());
+        for (int u = 0; u < (int)g.getNumVertices(); ++u) {
+            int start = g.getOffsets()[u+1] - (offsets[u+1]-offsets[u]);
+            for (int e = offsets[u]; e < offsets[u+1]; ++e) {
+                edgeIds[start + e - offsets[u]] = e;
+                edgeIds[cursor[neighbors[e]]++] = e;
+            }
+        }
+    }
+
+    void buildCommonNeighbors() {
+        if (!common.empty()) return;
+        int n = g.getNumVertices();
+        buildTriangles(nullptr);
+        common.resize(neighbors.size());
+        for (int a = 0; a < n; ++a) {
+            for (int ab = offsets[a]; ab < offsets[a+1]; ++ab) {
+                for (int t = triangleStart[ab]; t < triangleStart[ab+1]; ++t) {
+                    common[ab].push_back(triangleEnds[t]);
+                    common[middleEdge[t]].push_back(neighbors[ab]);
+                    common[farEdge[t]].push_back(a);
+                }
+            }
+        }
+        for (auto &row : common) std::sort(row.begin(),row.end());
+    }
+
+    void columns(int k, const int **column) {
+        if (edgeLeft.empty()) {
+            edgeLeft.resize(neighbors.size());
+            for (int a = 0; a < (int)g.getNumVertices(); ++a)
+                std::fill(edgeLeft.begin()+offsets[a],edgeLeft.begin()+offsets[a+1],a);
+        }
+        if (k == 2) {
+            column[1] = edgeLeft.data();
+            column[2] = neighbors.data();
+        } else {
+            if (vertexTriangleStart.empty()) {
+                triangleLeft.resize(triangleEnds.size());
+                triangleMiddle.resize(triangleEnds.size());
+                firstEdge.resize(triangleEnds.size());
+                for (int e = 0; e < (int)neighbors.size(); ++e) {
+                    int start = triangleStart[e], end = triangleStart[e+1];
+                    std::fill(triangleLeft.begin()+start,triangleLeft.begin()+end,edgeLeft[e]);
+                    std::fill(triangleMiddle.begin()+start,triangleMiddle.begin()+end,neighbors[e]);
+                    std::fill(firstEdge.begin()+start,firstEdge.begin()+end,e);
+                }
+                for (int o : offsets) vertexTriangleStart.push_back(triangleStart[o]);
+            }
+            column[1] = triangleLeft.data();
+            column[2] = triangleMiddle.data();
+            column[3] = firstEdge.data();
+            column[4] = triangleEnds.data();
+            column[5] = middleEdge.data();
+            column[6] = farEdge.data();
+        }
+    }
+
+    int triangleAt(int start, int left, int right, bool small) const {
+        if (small) {
+            uint64_t before = (uint64_t(1) << (right-start)) - 1;
+            return triangleStart[left] + __builtin_popcountll(links[left] & before);
+        }
+        return std::lower_bound(triangleEnds.begin()+triangleStart[left],
+                                triangleEnds.begin()+triangleStart[left+1],neighbors[right]) - triangleEnds.begin();
+    }
+
+    // Entry indexed by a subset of the bag vertices. In a forward ego graph,
+    // every edge is already indexed by the triangle it forms with its apex.
+    template<class F>
+    void indexed(int k, bool faceIds, F visit) const {
+        int id[1<<capacity]{};
+        for (int a = 0; a < (int)g.getNumVertices(); ++a) {
+            id[1] = a;
+            if (k == 1) { visit(id); continue; }
+            int start = offsets[a];
+            bool small = offsets[a+1]-start <= 64;
+            for (int ab = start; ab < offsets[a+1]; ++ab) {
+                int b = neighbors[ab];
+                id[2] = b;
+                id[3] = ab;
+                if (k == 2) { visit(id); continue; }
+                for (int t = triangleStart[ab]; t < triangleStart[ab+1]; ++t) {
+                    int ac = middleEdge[t], bc = farEdge[t];
+                    id[4] = triangleEnds[t];
+                    id[5] = ac;
+                    id[6] = bc;
+                    id[7] = t;
+                    if (k == 3) { visit(id); continue; }
+                    auto emit = [&](int abd, int acd) {
+                        int ad = middleEdge[abd], bd = farEdge[abd];
+                        id[8] = neighbors[ad];
+                        id[9] = ad;
+                        id[10] = bd;
+                        id[12] = farEdge[acd];
+                        if (faceIds) {
+                            id[11] = abd;
+                            id[13] = acd;
+                            id[14] = triangleAt(offsets[b],bc,bd,offsets[b+1]-offsets[b] <= 64);
+                        }
+                        visit(id);
+                    };
+                    if (small) {
+                        uint64_t ends = links[ab] & links[ac];
+                        while (ends) {
+                            int ad = start + __builtin_ctzll(ends);
+                            ends &= ends-1;
+                            emit(triangleAt(start,ab,ad,true),triangleAt(start,ac,ad,true));
+                        }
+                    } else {
+                        int acd = triangleStart[ac];
+                        for (int abd = t+1; abd < triangleStart[ab+1]; ++abd) {
+                            while (acd < triangleStart[ac+1] && triangleEnds[acd] < triangleEnds[abd]) ++acd;
+                            if (acd < triangleStart[ac+1] && triangleEnds[acd] == triangleEnds[abd]) emit(abd,acd);
+                        }
+                    }
+                }
+            }
+        }
+    }
+
+    template<class F>
+    void extendLargeClique(Order &v, int used, int k, int start, int end, F &visit) const {
+        if (used == k) {
+            visit(v);
+            return;
+        }
+        for (int e = start; e < end; ++e) {
+            int w = neighbors[e];
+            bool ok = true;
+            for (int i = 1; i < used; ++i)
+                if (!std::binary_search(neighbors.begin()+offsets[v[i]], neighbors.begin()+offsets[v[i]+1],w)) {
+                    ok = false;
+                    break;
+                }
+            if (ok) {
+                v[used] = w;
+                extendLargeClique(v, used+1, k, e+1, end, visit);
+            }
+        }
+
+    }
+};
+
+struct Table {
+    int arity;
+    // Store one entry per unordered boundary clique when every permutation
+    // gives the same number of extensions.
+    int stride;
+    std::vector<Count> values;
+};
+
+int permutationIndex(const Order &order, int n) {
+    int code = 0;
+    for (int i = 0; i < n; ++i) {
+        int smaller = 0;
+        for (int j = i+1; j < n; ++j) smaller += order[j] < order[i];
+        code = code * (n-i) + smaller;
+    }
+    return code;
+}
+
+struct Entry {
+    Mask subset;
+    int index;
+};
+
+Entry entry(const Table &t, const Order &bagIndices, int count) {
+    Mask mask = 0;
+    for (int i = 0; i < count; ++i) mask |= 1u << bagIndices[i];
+    return {mask, t.stride == 1 ? 0 : permutationIndex(bagIndices, count)};
+}
