+class Counter {
+    CliqueGraph graph;
+    const Triangle *tri;
+    Planner planner;
+    std::map<Key, Table> tables;
+
+    struct Operation {
+        std::array<Entry,capacity+1> entries{};
+        int multiplicity;
+    };
+
+    // Small bags have one column of IDs for each type of face. Each term
+    // is a gather/multiply/reduce over those columns. Prefix faces form
+    // consecutive ranges, so write the accumulator only once per range.
+    void contractColumns(int k, const std::vector<Operation> &ops,
+                         const std::vector<const Table*> &inputs, Table &out) {
+        const int *columns[8]{};
+        graph.columns(k,columns);
+        int rows = k == 2 ? graph.neighbors.size() : graph.triangleEnds.size();
+        for (const auto &op : ops) {
+            struct Source {
+                const int *ids;
+                const Count *counts;
+                int stride;
+            };
+            std::array<Source,capacity> src{};
+            // Products whose factors are all unary or symmetric are common.
+            bool unitStride = true;
+            for (size_t j = 0; j < inputs.size(); ++j) {
+                auto entry = op.entries[j+1];
+                src[j] = {columns[entry.subset],inputs[j]->values.data()+entry.index,inputs[j]->stride};
+                unitStride &= inputs[j]->stride == 1;
+            }
+            Entry dest = op.entries[0];
+            Count *result = out.values.data()+dest.index;
+            const int *group = nullptr, *targets = nullptr;
+            int groups = 0;
+            if (dest.subset == 1) {
+                group = k == 2 ? graph.offsets.data() : graph.vertexTriangleStart.data();
+                groups = graph.g.getNumVertices();
+            } else if (k == 3 && (dest.subset == 2 || dest.subset == 3)) {
+                group = graph.triangleStart.data();
+                groups = graph.neighbors.size();
+                if (dest.subset == 2) targets = graph.neighbors.data();
+            }
+            auto apply = [&](auto inputCount, auto unit) {
+                auto value = [&](int row) {
+                    Count v = op.multiplicity;
+                    for (int j = 0; j < inputCount; ++j) {
+                        int id = src[j].ids ? src[j].ids[row] : row;
+                        v *= src[j].counts[unit ? id : id*src[j].stride];
+                    }
+                    return v;
+                };
+                if (group) {
+                    for (int i = 0; i < groups; ++i) {
+                        Count sum = 0;
+                        for (int row = group[i]; row < group[i+1]; ++row) sum += value(row);
+                        result[(targets ? targets[i] : i)*out.stride] += sum;
+                    }
+                } else {
+                    const int *ids = columns[dest.subset];
+                    for (int row = 0; row < rows; ++row) result[(ids ? ids[row] : row)*out.stride] += value(row);
+                }
+            };
+            auto dispatch = [&](auto count) {
+                if (unitStride) apply(count,std::true_type{});
+                else apply(count,std::false_type{});
+            };
+            if (inputs.size() == 1) dispatch(std::integral_constant<int,1>{});
+            else if (inputs.size() == 2) dispatch(std::integral_constant<int,2>{});
+            else dispatch(int(inputs.size()));
+        }
+    }
+
+    std::vector<Count> fourEdgeCounts;
+
+    // Count cliques incident to each edge. Inside N+(a), a triangle b,c,d
+    // accounts for all four-cliques with minimum a. Popcounts sum all choices
+    // of the third vertex before any edge counter is touched.
+    void countFourEdges() {
+        if (!fourEdgeCounts.empty()) return;
+        fourEdgeCounts.resize(graph.neighbors.size());
+        for (int a = 0; a < (int)graph.g.getNumVertices(); ++a) {
+            int start = graph.offsets[a], end = graph.offsets[a+1];
+            if (end-start <= 64) {
+                uint64_t adjacent[64]{};
+                int incidence[64]{};
+                for (int ab = start; ab < end; ++ab) {
+                    for (int t = graph.triangleStart[ab]; t < graph.triangleStart[ab+1]; ++t)
+                        adjacent[graph.middleEdge[t]-start] |= uint64_t(1) << (ab-start);
+                    adjacent[ab-start] |= graph.links[ab];
+                }
+                for (int ab = start; ab < end; ++ab) {
+                    for (int t = graph.triangleStart[ab]; t < graph.triangleStart[ab+1]; ++t) {
+                        int c = graph.middleEdge[t] - start;
+                        int count = __builtin_popcountll(adjacent[ab-start] & adjacent[c]);
+                        fourEdgeCounts[graph.farEdge[t]] += count;
+                        incidence[ab-start] += count;
+                        incidence[c] += count;
+                    }
+                }
+                for (int ab = start; ab < end; ++ab) fourEdgeCounts[ab] += incidence[ab-start]/2;
+            } else {
+                Order v{a};
+                auto add = [&](const Order &q) {
+                    for (int i = 0; i < 4; ++i)
+                        for (int j = i+1; j < 4; ++j) ++fourEdgeCounts[graph.edge(q[i],q[j])];
+                };
+                graph.extendLargeClique(v,1,4,start,end,add);
+            }
+        }
+    }
+
+    void countFiveVertices(Table &out) {
+        for (int a = 0; a < (int)graph.g.getNumVertices(); ++a) {
+            int start = graph.offsets[a], end = graph.offsets[a+1];
+            if (end-start <= 64) {
+                uint64_t adjacent[64]{};
+                Count incidence[64]{};
+                for (int ab = start; ab < end; ++ab) {
+                    adjacent[ab-start] |= graph.links[ab];
+                    for (int t = graph.triangleStart[ab]; t < graph.triangleStart[ab+1]; ++t)
+                        adjacent[graph.middleEdge[t]-start] |= uint64_t(1) << (ab-start);
+                }
+                Count sum = 0;
+                for (int ab = start; ab < end; ++ab) {
+                    for (int t = graph.triangleStart[ab]; t < graph.triangleStart[ab+1]; ++t) {
+                        int ac = graph.middleEdge[t];
+                        uint64_t common = graph.links[ab] & graph.links[ac];
+                        int twice = 0;
+                        for (uint64_t m = common; m; m &= m-1) {
+                            int d = __builtin_ctzll(m);
+                            int count = __builtin_popcountll(common & adjacent[d]);
+                            twice += count;
+                            incidence[d] += count;
+                        }
+                        int count = twice/2;
+                        incidence[ab-start] += count;
+                        incidence[ac-start] += count;
+                        sum += count;
+                    }
+                }
+                out.values[a] += sum;
+                for (int ab = start; ab < end; ++ab) out.values[graph.neighbors[ab]] += incidence[ab-start];
+            } else {
+                Order v{a};
+                auto add = [&](const Order &q) { for (int x : q) ++out.values[x]; };
+                graph.extendLargeClique(v,1,5,start,end,add);
+            }
+        }
+        for (auto &v : out.values) v *= factorial[4];
+    }
+
+    void plainClique(int k, Table &out) {
+        int b = out.arity;
+        if (b == k) {
+            std::fill(out.values.begin(),out.values.end(),1);
+        } else if (k == 2) {
+            for (int v = 0; v < (int)out.values.size(); ++v) out.values[v] = graph.g.degree(v);
+        } else if (k == 3 && tri) {
+            for (int a = 0; a < (int)graph.g.getNumVertices(); ++a) {
+                for (int e = graph.offsets[a]; e < graph.offsets[a+1]; ++e) {
+                    Count count = tri->offset1[e+1]-tri->offset1[e];
+                    if (b == 2) out.values[e] = count;
+                    else {
+                        out.values[a] += count;
+                        out.values[graph.neighbors[e]] += count;
+                    }
+                }
+            }
+        } else if (k == 4 && b <= 2) {
+            countFourEdges();
+            for (int a = 0; a < (int)graph.g.getNumVertices(); ++a) {
+                for (int e = graph.offsets[a]; e < graph.offsets[a+1]; ++e) {
+                    Count count = 2*fourEdgeCounts[e];
+                    if (b == 2) out.values[e] = count;
+                    else {
+                        out.values[a] += count;
+                        out.values[graph.neighbors[e]] += count;
+                    }
+                }
+            }
+        } else if (k == 4 && b == 3 && tri) {
+            // Condition on the minimum of the three boundary vertices.
+            // Number its neighbors locally so a common extension is one bit
+            // in the intersection of the other two neighborhoods.
+            std::vector<int> position(graph.g.getNumVertices());
+            std::vector<uint64_t> bits;
+            for (int a = 0; a < (int)graph.g.getNumVertices(); ++a) {
+                int start = graph.offsets[a], end = graph.offsets[a+1];
+                if (graph.triangleStart[start] == graph.triangleStart[end]) continue;
+                ui degree;
+                auto ns = graph.g.getNeighbors(a,degree);
+                for (ui i = 0; i < degree; ++i) position[ns[i]] = i;
+                int words = (degree+63)/64;
+                // For a very large ego use the sorted intersection lists
+                // directly to keep the workspace linear in the data graph.
+                if (size_t(end-start)*words > graph.g.getNumEdges()) {
+                    for (int e = start; e < end; ++e) {
+                        for (int t = graph.triangleStart[e]; t < graph.triangleStart[e+1]; ++t) {
+                            int ac = graph.middleEdge[t];
+                            ui i = tri->offset1[e], j = tri->offset1[ac];
+                            int count = 0;
+                            while (i < tri->offset1[e+1] && j < tri->offset1[ac+1]) {
+                                VertexID x = tri->triend[i], y = tri->triend[j];
+                                count += x == y;
+                                i += x <= y;
+                                j += y <= x;
+                            }
+                            out.values[t] = count;
+                        }
+                    }
+                    continue;
+                }
+                bits.assign(size_t(end-start)*words,0);
+                for (int e = start; e < end; ++e) {
+                    auto row = bits.data()+size_t(e-start)*words;
+                    for (ui t = tri->offset1[e]; t < tri->offset1[e+1]; ++t) {
+                        int x = position[tri->triend[t]];
+                        row[x/64] |= uint64_t(1) << (x%64);
+                    }
+                }
+                for (int e = start; e < end; ++e) {
+                    auto x = bits.data()+size_t(e-start)*words;
+                    for (int t = graph.triangleStart[e]; t < graph.triangleStart[e+1]; ++t) {
+                        auto y = bits.data()+size_t(graph.middleEdge[t]-start)*words;
+                        int sum = 0;
+                        for (int w = 0; w < words; ++w) sum += __builtin_popcountll(x[w] & y[w]);
+                        out.values[t] = sum;
+                    }
+                }
+            }
+        } else if (k == 5) {
+            countFiveVertices(out);
+        } else {
+            std::vector<int> subsets;
+            for (int m = 1; m < 1<<k; ++m) if (population(m) == b) subsets.push_back(m);
+            graph.indexed(k,b >= 3,[&](const int *id) {
+                for (int m : subsets) out.values[id[m]] += factorial[k-b];
+            });
+        }
+    }
+
+    bool wantSquareEdges = false, squaresReady = false;
+    Child squareWeight[2]{};
+    std::vector<Count> fourWalkEdges, weightedCounts[2];
+
+    bool incident(const Shape &h, const Child &c) const {
+        int first = c.attachment[0];
+        if (c.boundary == 2) return first == 0 || c.attachment[1] == 0;
+        return first == 0 || (h.adj[0] >> first & 1);
+    }
+
+    // All square contractions use the same pair of two-step paths from a
+    // maximum vertex a to an opposite vertex b. For a five-vertex pattern,
+    // a weight outside this bag can only attach to one vertex or one edge.
+    // Accumulate every requested weight and projection in the same traversal.
+    void buildSquares() {
+        if (squaresReady) return;
+        squaresReady = true;
+        int n = graph.g.getNumVertices();
+        auto off = graph.g.getOffsets();
+        auto nb = graph.g.getNbors();
+        const Count *weights[2]{};
+        for (int k = 0; k < 2; ++k) if (squareWeight[k].boundary) {
+            weights[k] = evaluate(squareWeight[k].h,k+1).values.data();
+            weightedCounts[k].resize(n);
+        }
+        if (wantSquareEdges || weights[1]) graph.indexEdges();
+        if (wantSquareEdges) fourWalkEdges.resize(graph.neighbors.size());
+
+        // The innermost loop walks consecutive CSR arcs. Keep its weights
+        // and partial counts in that order and combine the two orientations
+        // of each edge after the traversal.
+        std::vector<ui> arcCounts, arcWeight;
+        if (wantSquareEdges) arcCounts.resize(graph.g.getNumEdges());
+        if (weights[1]) {
+            arcWeight.reserve(graph.edgeIds.size());
+            for (int id : graph.edgeIds) arcWeight.push_back(weights[1][id]);
+        }
+
+        auto traverse = [&](auto edgeCounts, auto vertexWeight, auto edgeWeight) {
+            std::vector<int> paths(n), touched;
+            // A leg weight is a degree or triangle support. Its sum over
+            // common neighbors is at most the number of directed data edges.
+            std::vector<ui> vertex(n), left(n), right(n);
+            std::vector<ui> limit(off,off+n);
+            for (int a = 0; a < n; ++a) {
+                size_t wedges = 0;
+                for (ui ax = off[a]; ax < limit[a]; ++ax) wedges += limit[nb[ax]] - off[nb[ax]];
+                bool sparse = wedges < size_t(a)/2 && (vertexWeight || edgeWeight);
+                Count diagVertex = 0, diagEdge = 0;
+                touched.clear();
+                auto gather = [&](auto list) {
+                    for (ui ax = off[a]; ax < limit[a]; ++ax) {
+                        int x = nb[ax];
+                        Count vx = 0, ex = 0;
+                        if (vertexWeight) { vx = weights[0][x]; diagVertex += vx; }
+                        if (edgeWeight) { ex = arcWeight[ax]; diagEdge += ex; }
+                        for (ui xb = off[x]; xb < limit[x]; ++xb) {
+                            int b = nb[xb];
+                            if (list && !paths[b]) touched.push_back(b);
+                            ++paths[b];
+                            if (vertexWeight) vertex[b] += vx;
+                            if (edgeWeight) {
+                                left[b] += ex;
+                                right[b] += arcWeight[xb];
+                            }
+                        }
+                    }
+                };
+                if (sparse) gather(std::true_type{}); else gather(std::false_type{});
+
+                Count tDiag = limit[a]-off[a];
+                Count vertexA = vertexWeight ? tDiag*tDiag*weights[0][a] : 0;
+                Count edgeA = tDiag*diagEdge;
+                auto reduce = [&](int b) {
+                    Count t = paths[b];
+                    if (vertexWeight) {
+                        vertexA += t*t*weights[0][b];
+                        weightedCounts[0][b] += t*t*weights[0][a];
+                    }
+                    if (edgeWeight) {
+                        edgeA += t*right[b];
+                        weightedCounts[1][b] += t*left[b];
+                    }
+                };
+                if (vertexWeight || edgeWeight) {
+                    if (sparse) { for (int b : touched) reduce(b); }
+                    else { for (int b = 0; b < a; ++b) reduce(b); }
+                }
+                if (vertexWeight) weightedCounts[0][a] += vertexA;
+                if (edgeWeight) weightedCounts[1][a] += edgeA;
+                for (ui ax = off[a]; ax < limit[a]; ++ax) {
+                    int x = nb[ax];
+                    Count plain = 0, vw = 0, ew = 0;
+                    for (ui xb = off[x]; xb < limit[x]; ++xb) {
+                        int b = nb[xb];
+                        if (edgeCounts) {
+                            int add = paths[b]-1;
+                            arcCounts[xb] += add;
+                            plain += add;
+                        }
+                        if (vertexWeight) vw += vertex[b];
+                        if (edgeWeight) ew += Count(left[b])+right[b];
+                    }
+                    if (edgeCounts) arcCounts[ax] += plain;
+                    if (vertexWeight) weightedCounts[0][x] += 2*vw+diagVertex;
+                    if (edgeWeight) weightedCounts[1][x] += ew+diagEdge;
+                }
+                if (sparse) {
+                    for (int b : touched) {
+                        paths[b] = 0;
+                        if (vertexWeight) vertex[b] = 0;
+                        if (edgeWeight) left[b] = right[b] = 0;
+                    }
+                } else {
+                    std::fill(paths.begin(),paths.begin()+a,0);
+                    if (vertexWeight) std::fill(vertex.begin(),vertex.begin()+a,0);
+                    if (edgeWeight) {
+                        std::fill(left.begin(),left.begin()+a,0);
+                        std::fill(right.begin(),right.begin()+a,0);
+                    }
+                }
+                for (ui e = off[a]; e < off[a+1]; ++e) ++limit[nb[e]];
+            }
+        };
+        auto run = [&](auto plain) {
+            if (weights[0] && weights[1]) traverse(plain,std::true_type{},std::true_type{});
+            else if (weights[0]) traverse(plain,std::true_type{},std::false_type{});
+            else if (weights[1]) traverse(plain,std::false_type{},std::true_type{});
+            else traverse(plain,std::false_type{},std::false_type{});
+        };
+        if (wantSquareEdges) run(std::true_type{}); else run(std::false_type{});
+        // A three-step walk across an edge either closes a simple square
+        // or repeats one of its endpoint vertices.
+        if (wantSquareEdges) {
+            for (size_t arc = 0; arc < arcCounts.size(); ++arc)
+                fourWalkEdges[graph.edgeIds[arc]] += arcCounts[arc];
+            for (int a = 0; a < n; ++a)
+                for (int e = graph.offsets[a]; e < graph.offsets[a+1]; ++e)
+                    fourWalkEdges[e] += Count(graph.g.degree(a))+graph.g.degree(graph.neighbors[e])-1;
+        }
+    }
+
+    void square(const Shape &h, const Plan &plan, const std::vector<const Table*> &inputs, Table &out) {
+        buildSquares();
+        if (out.arity == 2) { out.values = fourWalkEdges; return; }
+        if (!inputs.empty() && !incident(h,plan.children.front())) {
+            out.values = weightedCounts[inputs.front()->arity-1];
+            return;
+        }
+        const Table *w = inputs.empty() ? nullptr : inputs.front();
+        int vertex = w ? plan.children.front().attachment[0] : -1;
+        for (int a = 0; a < (int)graph.g.getNumVertices(); ++a) {
+            for (int e = graph.offsets[a]; e < graph.offsets[a+1]; ++e) {
+                int b = graph.neighbors[e];
+                Count aWeight = 1, bWeight = 1;
+                if (w && w->arity == 2) aWeight = bWeight = w->values[e];
+                else if (w) {
+                    aWeight = w->values[vertex == 0 ? a : b];
+                    bWeight = w->values[vertex == 0 ? b : a];
+                }
+                out.values[a] += fourWalkEdges[e]*aWeight;
+                out.values[b] += fourWalkEdges[e]*bWeight;
+            }
+        }
+    }
+
+    // Derivatives of the separator product give the local counts in each
+    // component. Compute the three possible marginals together while the
+    // common-neighbor histograms are resident in cache.
+    struct Marginals { std::vector<Count> pole, vertex, endpoint; };
+    std::map<std::pair<int,int>,Marginals> margins;
+    enum Projection { Pole = 1, Point = 2, Endpoint = 4 };
+    std::map<std::pair<int,int>,int> projections;
+    std::set<Key> inspected;
+
+    static Projection projection(const Poles &cut) {
+        if (cut.a == 0 || cut.b == 0) return Pole;
+        for (auto [x,y] : cut.groups)
+            if (x == 0 || y == 0) return y < 0 ? Point : Endpoint;
+        return Pole;
+    }
+
+    static std::pair<int,int> groupSizes(const Poles &cut) {
+        int edges = 0;
+        for (auto group : cut.groups) edges += group.second >= 0;
+        return {int(cut.groups.size())-edges,edges};
+    }
+
+    void inspect(const Shape &h, int b) {
+        if (!inspected.insert(h.key(b)).second) return;
+        auto plan = planner.choose(h,b);
+        if (!h.clique(plan.bag)) {
+            auto cut = findPoles(h,plan.bag,0);
+            if (population(plan.bag) == 4 && cut.groups.size() == 2) {
+                if (plan.children.empty() || incident(h,plan.children.front())) wantSquareEdges = true;
+                else {
+                    const Child &c = plan.children.front();
+                    squareWeight[c.boundary-1] = c;
+                }
+            } else if (cut.a >= 0) {
+                projections[groupSizes(cut)] |= projection(cut);
+            }
+        }
+        for (auto &c : plan.children) inspect(c.h,c.boundary);
+    }
+
+    // Tile the pole dimension. For each tile, stream each common-neighbor
+    // list once for its poles in this tile. The two-hop counts stay local to
+    // the tile, and a single scan serves all requested orbit projections.
+    template<class PathCount>
+    void edgeComponents(Marginals &result, int wanted) {
+        int n = graph.g.getNumVertices();
+        int m = graph.neighbors.size();
+        if (!tri) graph.buildCommonNeighbors();
+        // Longer triangle lists amortize a wider tile. Bound the scratch
+        // space for the tile independently of the number of data vertices.
+        Count entries = tri ? tri->triangleCnt : graph.triangleEnds.size()*3;
+        size_t rowBytes = size_t(n)*(sizeof(PathCount) + ((wanted & Point) ? sizeof(int) : 0));
+        int width = 1;
+        Count target = entries/std::max(1,m) * ((wanted & Point) ? 4 : 8);
+        while (width < 256 && width*2 <= target && 2*width*rowBytes <= 4*1024*1024) width *= 2;
+        int shift = __builtin_ctz(width);
+        struct Segment { int edge, first, last; };
+        std::vector<std::vector<Segment>> segments((n+width-1)/width);
+        std::vector<int> incident(n), left(m);
+        auto common = [&](int e, auto visit) {
+            if (tri) visit(tri->triend+tri->offset1[e],int(tri->offset1[e+1]-tri->offset1[e]));
+            else visit(graph.common[e].data(),int(graph.common[e].size()));
+        };
+        for (int x = 0; x < n; ++x) {
+            for (int e = graph.offsets[x]; e < graph.offsets[x+1]; ++e) {
+                left[e] = x;
+                common(e,[&](const auto *row,int size) {
+                    int j = 0;
+                    while (j < size) {
+                        int block = row[j] >> shift;
+                        int begin = j;
+                        do { ++incident[row[j++]]; } while (j < size && (row[j] >> shift) == block);
+                        segments[block].push_back({e,begin,j});
+                    }
+                });
+            }
+        }
+        auto off = graph.g.getOffsets();
+        auto nb = graph.g.getNbors();
+        std::vector<ui> limit(off,off+n);
+        std::vector<PathCount> paths(width*size_t(n));
+        std::vector<int> inside;
+        if (wanted & Point) inside.resize(width*size_t(n));
+        bool full = (wanted & Pole) && !(wanted & Point);
+        bool needPaths = wanted & (Pole | Endpoint);
+        for (int first = 0; first < n; first += width) {
+            int end = std::min(first+width,n);
+            for (int a = first; a < end; ++a) {
+                auto row = paths.data()+size_t(a-first)*n;
+                if (needPaths) std::fill(row,row+(full ? n : a+1),0);
+                if (wanted & Point) {
+                    auto h = inside.data()+size_t(a-first)*n;
+                    std::fill(h,h+a+1,0);
+                    h[a] = incident[a];
+                }
+                for (ui ax = off[a]; ax < off[a+1]; ++ax) {
+                    int x = nb[ax];
+                    ++limit[x];
+                    if (needPaths && incident[a])
+                        for (ui xb = off[x]; xb < (full ? off[x+1] : limit[x]); ++xb) ++row[nb[xb]];
+                }
+            }
+            auto project = [&](auto wantPoint, auto wantEnd, auto fullPairs) {
+                for (auto segment : segments[first >> shift]) {
+                    int e = segment.edge;
+                    common(e,[&](const auto *row,int size) {
+                        Count endSum = 0;
+                        for (int i = segment.first; i < segment.last; ++i) {
+                            int a = row[i];
+                            size_t start = size_t(a-first)*n;
+                            auto p = paths.data()+start;
+                            auto h = wantPoint ? inside.data()+start : nullptr;
+                            // With 16-bit path counts this dot product fits
+                            // in 32 bits: both factors are bounded by degree.
+                            using Sum = std::conditional_t<sizeof(PathCount)==2,uint32_t,Count>;
+                            Sum sum = 0;
+                            int count = fullPairs ? size : i;
+                            for (int j = 0; j < count; ++j) {
+                                int b = row[j];
+                                if (wantPoint) ++h[b];
+                                if (wantEnd || fullPairs) sum += p[b];
+                            }
+                            if (fullPairs) result.pole[a] += 2*Count(sum);
+                            if (wantEnd) endSum += fullPairs ? Count(sum) : 2*Count(sum)+p[a];
+                        }
+                        if (wantEnd) {
+                            result.endpoint[left[e]] += endSum;
+                            result.endpoint[graph.neighbors[e]] += endSum;
+                        }
+                    });
+                }
+            };
+            if (wanted & Point) {
+                if (wanted & Endpoint) project(std::true_type{},std::true_type{},std::false_type{});
+                else project(std::true_type{},std::false_type{},std::false_type{});
+            } else if (full) {
+                if (wanted & Endpoint) project(std::false_type{},std::true_type{},std::true_type{});
+                else project(std::false_type{},std::false_type{},std::true_type{});
+            } else project(std::false_type{},std::true_type{},std::false_type{});
+
+            if (!(wanted & Point)) continue;
+            for (int a = first; a < end; ++a) {
+                if (!incident[a]) continue;
+                auto h = inside.data()+size_t(a-first)*n;
+                if (wanted & Pole) {
+                    auto p = paths.data()+size_t(a-first)*n;
+                    Count sum = 2*Count(p[a])*h[a];
+                    for (int b = 0; b < a; ++b) {
+                        Count term = 2*Count(p[b])*h[b];
+                        sum += term;
+                        result.pole[b] += term;
+                    }
+                    result.pole[a] += sum;
+                }
+                for (ui ax = off[a]; ax < off[a+1]; ++ax) {
+                    int x = nb[ax];
+                    Count sum = 0;
+                    for (ui xb = off[x]; xb < limit[x] && nb[xb] < (ui)a; ++xb) sum += h[nb[xb]];
+                    result.vertex[x] += 4*sum + 2*Count(h[a]);
+                }
+            }
+        }
+    }
+
+    void pointComponents(int points, int wanted, Marginals &result) {
+        int n = graph.g.getNumVertices();
+        auto off = graph.g.getOffsets();
+        auto nb = graph.g.getNbors();
+        std::vector<ui> limit(off,off+n);
+        std::vector<int> paths(n);
+        std::vector<Count> derivative(n);
+        for (int a = 0; a < n; ++a) {
+            std::fill(paths.begin(),paths.begin()+a+1,0);
+            for (ui ax = off[a]; ax < off[a+1]; ++ax) {
+                int x = nb[ax];
+                ++limit[x];
+                for (ui xb = off[x]; xb < limit[x]; ++xb) ++paths[nb[xb]];
+            }
+            Count sum = 0;
+            for (int b = 0; b <= a; ++b) {
+                Count d = 1;
+                for (int i = 1; i < points; ++i) d *= paths[b];
+                if (wanted & Pole) {
+                    Count term = d*paths[b];
+                    sum += term;
+                    if (b != a) result.pole[b] += term;
+                }
+                derivative[b] = d*(1+(a != b));
+            }
+            result.pole[a] += sum;
+            if (wanted & Point) {
+                for (ui ax = off[a]; ax < off[a+1]; ++ax) {
+                    int x = nb[ax];
+                    Count total = 0;
+                    for (ui xb = off[x]; xb < limit[x]; ++xb) total += derivative[nb[xb]];
+                    result.vertex[x] += total;
+                }
+            }
+        }
+    }
+
+    void twinMarginals(const Poles &cut, Table &out) {
+        auto sizes = groupSizes(cut);
+        auto [points,edges] = sizes;
+        auto &result = margins[sizes];
+        int wanted = projections[sizes];
+        int n = graph.g.getNumVertices();
+        if (result.pole.empty()) {
+            result.pole.resize(n);
+            result.vertex.resize(n);
+            result.endpoint.resize(n);
+            if (edges) {
+                ui maxDegree = 0;
+                for (int v = 0; v < n; ++v) maxDegree = std::max(maxDegree,graph.g.degree(v));
+                if (maxDegree <= UINT16_MAX) edgeComponents<uint16_t>(result,wanted);
+                else edgeComponents<ui>(result,wanted);
+            } else {
+                pointComponents(points,wanted,result);
+            }
+        }
+        auto role = projection(cut);
+        out.values = role == Pole ? result.pole : role == Point ? result.vertex : result.endpoint;
+    }
+
+    // Condition a dominating vertex on its data image. All remaining
+    // variables range over its induced neighborhood.
+    std::vector<Count> apexCounts, neighborCounts;
+
+    void sumEgos(int pivot, Table &out) {
+        if (apexCounts.empty()) {
+            graph.indexEdges();
+            if (!tri) graph.buildCommonNeighbors();
+            int n = graph.g.getNumVertices();
+            apexCounts.assign(n,0);
+            neighborCounts.assign(n,0);
+            std::vector<int> local(n), offsets, adj, paths, limit;
+            std::vector<Count> counts;
+            auto base = graph.g.getOffsets();
+            for (int v = 0; v < n; ++v) {
+                ui size;
+                auto names = graph.g.getNeighbors(v,size);
+                for (ui i = 0; i < size; ++i) local[names[i]] = i;
+                offsets.assign(size+1,0);
+                adj.clear();
+                for (ui i = 0; i < size; ++i) {
+                    int e = graph.edgeIds[base[v]+i];
+                    if (tri) {
+                        for (ui t = tri->offset1[e]; t < tri->offset1[e+1]; ++t)
+                            adj.push_back(local[tri->triend[t]]);
+                    } else {
+                        for (int y : graph.common[e]) adj.push_back(local[y]);
+                        std::sort(adj.begin()+offsets[i],adj.end());
+                    }
+                    offsets[i+1] = adj.size();
+                }
+                counts.assign(size,0);
+                paths.resize(size);
+                limit = offsets;
+                for (ui a = 0; a < size; ++a) {
+                    std::fill(paths.begin(),paths.begin()+a,0);
+                    for (int ax = offsets[a]; ax < limit[a]; ++ax) {
+                        int x = adj[ax];
+                        for (int xb = offsets[x]; xb < limit[x]; ++xb) ++paths[adj[xb]];
+                    }
+                    Count sum = 0;
+                    for (int ax = offsets[a]; ax < limit[a]; ++ax) {
+                        int x = adj[ax];
+                        Count add = 0;
+                        for (int xb = offsets[x]; xb < limit[x]; ++xb) {
+                            int b = adj[xb], others = paths[b]-1;
+                            counts[b] += others;
+                            add += others;
+                        }
+                        sum += add;
+                        counts[x] += 2*add;
+                    }
+                    Count degree = offsets[a+1]-offsets[a];
+                    counts[a] += sum + degree*degree;
+                    for (int ax = offsets[a]; ax < offsets[a+1]; ++ax) {
+                        int x = adj[ax];
+                        ++limit[x];
+                        counts[x] += degree-1;
+                    }
+                }
+                for (ui a = 0; a < size; ++a) {
+                    apexCounts[v] += counts[a];
+                    neighborCounts[names[a]] += counts[a];
+                }
+            }
+        }
+        out.values = pivot == 0 ? apexCounts : neighborCounts;
+    }
+
+    template<int lanes>
+    void cycleWalks(Table &out) {
+        // Rotate the maximum of the closed walk to the first position. Two
+        // steps from the maximum give a vector p. The middle edge multiplies
+        // p by the adjacency matrix. Process several maxima together so each
+        // adjacency lookup supplies a contiguous vector for that product.
+        struct alignas(lanes*sizeof(int)) Row { int x[lanes]; };
+        int n = graph.g.getNumVertices();
+        auto off = graph.g.getOffsets();
+        auto nb = graph.g.getNbors();
+        graph.indexEdges();
+        std::vector<Row> paths(n), extension(n);
+        std::vector<int> wedgeEnd(graph.g.getNumEdges());
+        std::vector<ui> limit(off,off+n);
+        std::vector<int> forwardEnd, touched;
+        if constexpr (lanes == 1) forwardEnd = graph.offsets;
+        for (int s = 0; s < n; ++s) {
+            int end = off[s+1]-(graph.offsets[s+1]-graph.offsets[s]);
+            for (int e = off[s]; e < end; ++e) {
+                int x = nb[e];
+                wedgeEnd[e] = off[x+1] - graph.offsets[x+1] + graph.edgeIds[e]+1;
+            }
+        }
+        for (int first = 0; first < n; first += lanes) {
+            int end = std::min(first+lanes,n);
+            if constexpr (lanes == 1) touched.clear();
+            else std::fill(paths.begin(),paths.begin()+end,Row{});
+            for (int s = first; s < end; ++s) {
+                int lane = s-first;
+                ui low = limit[s];
+                for (ui e = off[s]; e < off[s+1]; ++e) ++limit[nb[e]];
+                for (ui sx = off[s]; sx < low; ++sx) {
+                    int x = nb[sx];
+                    if constexpr (lanes == 1) ++forwardEnd[x];
+                    for (int xt = off[x]; xt < wedgeEnd[sx]; ++xt) {
+                        int t = nb[xt];
+                        if constexpr (lanes == 1) {
+                            if (!paths[t].x[0]) touched.push_back(t);
+                        }
+                        ++paths[t].x[lane];
+                    }
+                }
+            }
+            if constexpr (lanes == 1) {
+                for (int u : touched) extension[u].x[0] = 0;
+                for (int u : touched) {
+                    int sum = 0, weight = paths[u].x[0];
+                    for (int e = graph.offsets[u]; e < forwardEnd[u]; ++e) {
+                        int v = graph.neighbors[e];
+                        sum += paths[v].x[0];
+                        if (paths[v].x[0]) extension[v].x[0] += 2*weight;
+                    }
+                    extension[u].x[0] += 2*sum;
+                }
+            } else for (int u = 0; u < end; ++u) {
+                bool active = false;
+                for (int j = 0; j < lanes; ++j) active |= paths[u].x[j] != 0;
+                if (!active) continue;
+                Row sum{};
+                for (ui e = off[u]; e < limit[u]; ++e) {
+                    const Row &v = paths[nb[e]];
+                    for (int j = 0; j < lanes; ++j) sum.x[j] += v.x[j];
+                }
+                for (int j = 0; j < lanes; ++j) extension[u].x[j] = 2*sum.x[j];
+            }
+            // A repeated maximum can occur at position two or three. Keep
+            // one of those orientations to break the tie.
+            for (int s = first; s < end; ++s) {
+                int j = s-first;
+                extension[s].x[j] /= 2;
+                int low = off[s+1]-(graph.offsets[s+1]-graph.offsets[s]);
+                for (int sx = off[s]; sx < low; ++sx) {
+                    int u = nb[sx];
+                    if (paths[u].x[j]) extension[u].x[j] -= paths[s].x[j];
+                }
+            }
+            Count anchored[lanes]{};
+            auto accumulate = [&](int u) {
+                Count total = 0;
+                for (int j = 0; j < lanes; ++j) {
+                    Count term = Count(paths[u].x[j])*extension[u].x[j];
+                    anchored[j] += term;
+                    total += term;
+                }
+                out.values[u] += total;
+            };
+            if constexpr (lanes == 1) {
+                for (int u : touched) {
+                    accumulate(u);
+                    paths[u].x[0] = 0;
+                }
+            } else {
+                for (int u = 0; u < end; ++u) accumulate(u);
+            }
+            for (int s = first; s < end; ++s) {
+                int j = s-first;
+                out.values[s] += anchored[j]/2;
+                int low = off[s+1]-(graph.offsets[s+1]-graph.offsets[s]);
+                for (int sx = off[s]; sx < low; ++sx) {
+                    int x = nb[sx];
+                    Count sum = 0;
+                    for (int xt = off[x]; xt < wedgeEnd[sx]; ++xt) sum += extension[nb[xt]].x[j];
+                    out.values[x] += sum;
+                }
+            }
+        }
+    }
+
+    void sumOddCycle(Table &out) {
+        Count n = graph.g.getNumVertices(), steps = 0;
+        for (int x = 0; x < n; ++x)
+            steps += Count(graph.offsets[x+1]-graph.offsets[x])*graph.g.degree(x);
+        if (steps*8 < n*n) cycleWalks<1>(out);
+        else cycleWalks<8>(out);
+    }
+
+    Table &evaluate(const Shape &h, int b) {
+        auto key = h.key(b);
+        auto it = tables.find(key);
+        if (it != tables.end()) return it->second;
+
+        Plan plan = planner.choose(h,b);
+        int k = population(plan.bag);
+        if (b >= 3 || (h.clique(plan.bag) && (k >= 4 || (k == 3 && (!tri || !plan.children.empty())))))
+            graph.buildTriangles(tri);
+        Order p{0,1,2,3,4};
+        bool symmetric = true;
+        while (std::next_permutation(p.begin(),p.begin()+b))
+            if (h.induced(p,h.n).key(b) != key) { symmetric = false; break; }
+        int stride = symmetric ? 1 : factorial[b];
+        int size = b == 1 ? graph.g.getNumVertices() : b == 2 ? graph.neighbors.size() : graph.triangleEnds.size();
+        Table &out = tables.emplace(key, Table{b, stride, std::vector<Count>(size*stride)}).first->second;
+
+        std::vector<const Table*> inputs;
+        for (const auto &child : plan.children) inputs.push_back(&evaluate(child.h,child.boundary));
+
+        if (!h.clique(plan.bag)) {
+            Poles cut = findPoles(h,plan.bag,0);
+            if (cut.a >= 0) {
+                if (k == 4 && cut.groups.size() == 2) square(h,plan,inputs,out);
+                else twinMarginals(cut,out);
+            } else {
+                int pivot = egoPivot(h,plan.bag);
+                if (pivot >= 0) sumEgos(pivot,out);
+                else sumOddCycle(out);
+            }
+            return out;
+        }
+
+        if (inputs.empty()) {
+            plainClique(k,out);
+            return out;
+        }
+
+        Order pos{};
+        int index = 0;
+        for (int i = 0; i < h.n; ++i) if (plan.bag >> i & 1) pos[i] = index++;
+
+        Order perm{0,1,2,3,4};
+        std::map<std::vector<int>,int> combined;
+        do {
+            Order image{};
+            for (int i = 0; i < h.n; ++i) image[i] = perm[pos[i]];
+            if (symmetric && !std::is_sorted(image.begin(),image.begin()+b)) continue;
+            auto slot = entry(out,image,b);
+            std::vector<int> code{int(slot.subset)*128+slot.index};
+            for (size_t i = 0; i < inputs.size(); ++i) {
+                const Child &c = plan.children[i];
+                Order sub{};
+                for (int j = 0; j < c.boundary; ++j) sub[j] = image[c.attachment[j]];
+                auto e = entry(*inputs[i],sub,c.boundary);
+                code.push_back(int(e.subset)*128 + e.index);
+            }
+            ++combined[code];
+        } while (std::next_permutation(perm.begin(),perm.begin()+k));
+
+        std::vector<Operation> ops;
+        Mask used = 0;
+        for (auto &item : combined) {
+            Operation op{};
+            op.multiplicity = item.second;
+            int j = 0;
+            for (int c : item.first) {
+                Mask mask = c/128;
+                op.entries[j++] = {mask,c%128};
+                used |= 1u << mask;
+            }
+            ops.push_back(op);
+        }
+        if (k == 2 || k == 3) {
+            contractColumns(k,ops,inputs,out);
+            return out;
+        }
+        bool faces = false;
+        for (int mask = 1; mask < 1<<k; ++mask)
+            if ((used & (1u << mask)) && population(mask) >= 3) faces = true;
+        auto apply = [&](auto inputCount) {
+            graph.indexed(k,faces,[&](const int *id) {
+                for (const auto &op : ops) {
+                    Count product = op.multiplicity;
+                    for (int i = 0; i < inputCount; ++i) {
+                        const Entry &e = op.entries[i+1];
+                        product *= inputs[i]->values[id[e.subset]*inputs[i]->stride+e.index];
+                    }
+                    const Entry &e = op.entries[0];
+                    out.values[id[e.subset]*stride+e.index] += product;
+                }
+            });
+        };
+        if (inputs.size() == 1) apply(std::integral_constant<int,1>{});
+        else if (inputs.size() == 2) apply(std::integral_constant<int,2>{});
+        else apply(int(inputs.size()));
+        return out;
+    }
+
+public:
+    Counter(const DataGraph &g, const Triangle *t) : graph(g), tri(t) {}
+
+    using Terms = std::map<Key,std::pair<Shape,int>>;
+
+    bool prepare(const PatternGraph &p, Terms &terms) {
+        if (!p.getNumVertices() || p.getNumVertices() > capacity || p.getOrbitType() != 1) return false;
+        // Mobius inversion on the partition lattice excludes all collisions
+        // in a homomorphism. Blocks containing an edge would create a loop.
+        int n = p.getNumVertices();
+        Order block{};
+        auto partitions = [&](auto &&self, int i, int blocks) -> void {
+            if (i < n) {
+                for (int b = 0; b <= blocks; ++b) {
+                    bool valid = true;
+                    for (int j = 0; j < i; ++j)
+                        if (block[j] == b && p.isEdge(i,j)) valid = false;
+                    if (valid) {
+                        block[i] = b;
+                        self(self, i+1, blocks + (b == blocks));
+                    }
+                }
+                return;
+            }
+            Shape q;
+            q.n = blocks;
+            Order sizes{};
+            for (int j = 0; j < n; ++j) {
+                ++sizes[block[j]];
+                for (int l = 0; l < j; ++l)
+                    if (p.isEdge(l,j)) q.add(block[l],block[j]);
+            }
+            int mu = (n-blocks)%2 ? -1 : 1;
+            for (int j = 0; j < blocks; ++j) mu *= factorial[sizes[j]-1];
+            auto &term = terms[q.key(1)];
+            term.first = q;
+            term.second += mu;
+        };
+        partitions(partitions,1,1);
+        for (auto &item : terms)
+            if (item.second.second && !planner.supports(item.second.first,1)) return false;
+        for (auto &item : terms) if (item.second.second) inspect(item.second.first,1);
+        return true;
+    }
+
+    void count(const Terms &terms, int divisor, std::vector<Count> &result) {
+        result.assign(graph.g.getNumVertices(),0);
+        for (auto &item : terms) {
+            int weight = item.second.second;
+            if (!weight) continue;
+            const auto &h = evaluate(item.second.first,1).values;
+            for (size_t i = 0; i < result.size(); ++i) result[i] += h[i]*weight;
+        }
+        for (auto &v : result) v /= divisor;
+    }
+};
+
+} // namespace
+
+void countShared(const DataGraph &data, const Triangle *triangles,
+                 std::vector<PatternGraph> &patterns, std::vector<std::string> &files,
+                 const std::string &resultPath) {
+    Counter counter(data,triangles);
+    std::vector<PatternGraph> remaining;
+    std::vector<std::string> names;
+    std::vector<Count> result;
+    std::vector<Counter::Terms> queries(patterns.size());
+    std::vector<bool> supported(patterns.size());
+    for (size_t i = 0; i < patterns.size(); ++i)
+        supported[i] = counter.prepare(patterns[i],queries[i]);
+    for (size_t i = 0; i < patterns.size(); ++i) {
+        if (supported[i]) {
+            counter.count(queries[i],patterns[i].getDivideFactor(),result);
+            if (!resultPath.empty()) saveCount(resultPath+"/"+files[i], result.data(), data, 1);
+        } else {
+            remaining.push_back(patterns[i]);
+            names.push_back(files[i]);
+        }
+    }
+    remaining.swap(patterns);
+    names.swap(files);
+}
