+namespace batch {
+
+bool Shape::clique(Mask s) const {
+    for (int i = 0; i < n; ++i)
+        if ((s >> i & 1) && (s & ~(adj[i] | (1u << i)))) return false;
+    return true;
+}
+
+Shape Shape::induced(const Order &order, int size) const {
+    Shape h;
+    h.n = size;
+    for (int j = 1; j < size; ++j)
+        for (int i = 0; i < j; ++i)
+            if (adj[order[i]] >> order[j] & 1) h.add(i, j);
+    return h;
+}
+
+// The first b vertices are the ordered boundary. Canonicalize the rest so
+// isomorphic factors from different queries share one materialization.
+Key Shape::key(int b) const {
+    Order p{0, 1, 2, 3, 4};
+    Mask best = ~0u;
+    do {
+        Mask code = 0;
+        for (int j = 1; j < n; ++j)
+            for (int i = 0; i < j; ++i)
+                code = 2 * code + ((adj[p[i]] >> p[j]) & 1);
+        best = std::min(best, code);
+    } while (std::next_permutation(p.begin() + b, p.begin() + n));
+    return {n, b, best};
+}
+
+static std::vector<Child> split(const Shape &h, Mask bag) {
+    std::vector<Child> result;
+    Mask rest = h.all() ^ bag;
+    while (rest) {
+        Mask component = rest & -rest;
+        Mask reach = 0, last;
+        do {
+            last = component;
+            for (int i = 0; i < h.n; ++i)
+                if (component >> i & 1) reach |= h.adj[i];
+            component |= rest & reach;
+        } while (last != component);
+        rest ^= component;
+        Order p{};
+        int size = 0;
+        for (int i = 0; i < h.n; ++i)
+            if (bag & reach & (1u << i)) p[size++] = i;
+        Child c;
+        c.boundary = size;
+        c.attachment = p;
+        for (int i = 0; i < h.n; ++i)
+            if (component >> i & 1) p[size++] = i;
+        c.h = h.induced(p, size);
+        result.push_back(c);
+    }
+    return result;
+}
+
+Poles findPoles(const Shape &h, Mask bag, int preferred) {
+    Poles best;
+    int bestScore = -1;
+    for (int i = 0; i < h.n; ++i) for (int j = i+1; j < h.n; ++j) {
+        Mask pair = (1u << i) | (1u << j);
+        if ((bag & pair) != pair) continue;
+        Mask rest = bag ^ pair;
+        if (!rest || (h.adj[i] & bag) != rest || (h.adj[j] & bag) != rest) continue;
+        Poles cut{i,j,{}};
+        int score = (i == preferred || j == preferred);
+        bool ok = true;
+        for (int x = 0; x < h.n; ++x) if (rest >> x & 1) {
+            Mask links = rest & h.adj[x];
+            if (population(links) > 1) { ok = false; break; }
+            int y = links ? __builtin_ctz(links) : -1;
+            if (y < 0 || x < y) cut.groups.emplace_back(x,y);
+        }
+        if (ok && cut.groups.size() >= 2 && score > bestScore) {
+            bestScore = score;
+            best = std::move(cut);
+        }
+    }
+    return best;
+}
+
+int egoPivot(const Shape &h, Mask bag) {
+    for (int i = 0; i < h.n; ++i) {
+        if (!(bag >> i & 1)) continue;
+        Mask rest = bag ^ (1u << i);
+        if ((h.adj[i] & bag) != rest) continue;
+        auto cut = findPoles(h,rest,-1);
+        if (cut.a >= 0 && cut.groups.size() == 2 && std::all_of(cut.groups.begin(),cut.groups.end(),
+                                     [](auto g){ return g.second < 0; })) return i;
+    }
+    return -1;
+}
+
+static bool isCycle(const Shape &h, Mask bag) {
+    for (int i = 0; i < h.n; ++i)
+        if ((bag >> i & 1) && population(h.adj[i] & bag) != 2) return false;
+    return true;
+}
+
+Plan Planner::choose(const Shape &h, int b) {
+    Mask required = (1u << b) - 1;
+    Plan best;
+    int cost = 1000000;
+    for (Mask s = required; s <= h.all(); ++s) {
+        if ((s & required) != required) continue;
+        bool complete = h.clique(s);
+        if (!complete && population(s) < 4) continue;
+        if (!complete && findPoles(h,s,0).a < 0 &&
+            !(b == 1 && s == h.all() && (egoPivot(h,s) >= 0 || isCycle(h,s)))) continue;
+        auto children = split(h, s);
+        // Prefer a small clique separator. A non-clique bag requires
+        // aggregating two-step paths in addition to its boundary tables.
+        int price = (1 << (3 * population(s))) + (complete ? 0 : 100000);
+        bool ok = true;
+        for (auto &c : children) {
+            Mask boundary = 0;
+            for (int i = 0; i < c.boundary; ++i) boundary |= 1u << c.attachment[i];
+            if (c.h.n == h.n || !c.boundary || !h.clique(boundary) || !supports(c.h, c.boundary)) {
+                ok = false;
+                break;
+            }
+            price += 1 << (3 * c.boundary);
+        }
+        if (ok && price < cost) {
+            cost = price;
+            best = {s, std::move(children)};
+        }
+    }
+    return best;
+}
+
+bool Planner::supports(const Shape &h, int b) {
+    auto key = h.key(b);
+    auto it = possible.find(key);
+    if (it != possible.end()) return it->second;
+    return possible[key] = choose(h, b).bag != 0;
+}
+
+} // namespace batch
