+namespace batch {
+
+constexpr int capacity = 5;
+constexpr int factorial[] = {1, 1, 2, 6, 24, 120};
+using Order = std::array<int, capacity>;
+using Mask = unsigned;
+using Key = std::tuple<int, int, Mask>;
+
+inline int population(Mask set) { return __builtin_popcount(set); }
+
+struct Shape {
+    int n = 0;
+    Mask adj[capacity]{};
+
+    void add(int i, int j) {
+        adj[i] |= 1u << j;
+        adj[j] |= 1u << i;
+    }
+
+    Mask all() const { return (1u << n) - 1; }
+
+    bool clique(Mask s) const;
+    Shape induced(const Order &order, int size) const;
+    Key key(int boundarySize) const;
+
+};
+
+struct Child {
+    Shape h;
+    int boundary;
+    Order attachment{};
+};
+
+// An open two-vertex separator whose other vertices are common neighbors.
+// The components on the far side of the separator can be accumulated
+// independently, one data vertex (or one data edge) at a time.
+struct Poles {
+    int a = -1, b = -1;
+    std::vector<std::pair<int,int>> groups;
+};
+
+Poles findPoles(const Shape &h, Mask bag, int preferred);
+int egoPivot(const Shape &h, Mask bag);
+
+struct Plan {
+    Mask bag = 0;
+    std::vector<Child> children;
+};
+
+class Planner {
+    std::map<Key, bool> possible;
+public:
+    Plan choose(const Shape &h, int boundarySize);
+    bool supports(const Shape &h, int boundarySize);
+};
+
+} // namespace batch
+
 #endif //SCOPE_FOREST_H
